from collections import Counter
from itertools import combinations


def _regular_subsequences(indices):
    vals = sorted(indices)
    values = set(vals)
    found = set()
    for a, b in combinations(vals, 2):
        step = b - a
        seq = []
        x = a
        while x in values:
            seq.append(x)
            x += step
        if len(seq) >= 2:
            found.add(tuple(seq))
    return sorted(found, key=len, reverse=True)


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    best = None

    # Divider lines carry a rail color across most of each row/column. Their
    # intersection values encode the compact output symbol matrix.
    for rail in colors:
        row_candidates = [r for r in range(h) if sum(v == rail for v in grid[r]) >= 0.60 * w]
        col_candidates = [c for c in range(w) if sum(grid[r][c] == rail for r in range(h)) >= 0.60 * h]
        for rows in _regular_subsequences(row_candidates):
            for cols in _regular_subsequences(col_candidates):
                # Panel interiors reveal ordinary fill, distinct from rails.
                inner = [grid[r][c] for r in range(h) for c in range(w)
                         if r not in rows and c not in cols and grid[r][c] != rail]
                if not inner:
                    continue
                fill = Counter(inner).most_common(1)[0][0]

                # A tile emits a marker only if its four corners all match;
                # otherwise it takes the ordinary fill color.
                out = []
                for r0, r1 in zip(rows, rows[1:]):
                    row = []
                    for c0, c1 in zip(cols, cols[1:]):
                        corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
                        value = corners[0]
                        if value in (rail, fill) or any(v != value for v in corners):
                            value = fill
                        row.append(value)
                    out.append(row)

                # Trim the empty perimeter around the encoded marker map.
                marked = [(r, c) for r, row in enumerate(out) for c, v in enumerate(row) if v != fill]
                if marked:
                    r0, r1 = min(r for r, _ in marked), max(r for r, _ in marked)
                    c0, c1 = min(c for _, c in marked), max(c for _, c in marked)
                    compact = [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
                else:
                    compact = out
                score = (len(marked), len(rows) * len(cols),
                         len(compact) * len(compact[0]) if compact else 0)
                if best is None or score > best[0]:
                    best = (score, compact)
    if best is None:
        raise ValueError('No regular marker lattice found')
    return best[1]


